      wordProblems: [
        { id: "wp-2.9A-1", emoji: "🌱📏", scene: "School garden club measuring a new seedling with inch tiles", prompt: { en: "A seedling is measured with inch tiles laid end-to-end, no gaps or overlaps. It takes 7 tiles to cover it. How many inches long is the seedling?", es: "Una plántula se mide con fichas de una pulgada de extremo a extremo, sin espacios ni superposiciones. Se necesitan 7 fichas para cubrirla. ¿Cuántas pulgadas mide?", ur: "ایک پودے کو انچ ٹائلوں سے بغیر خلا کے ناپا جاتا ہے۔ اسے ڈھکنے کے لیے 7 ٹائلیں لگتی ہیں۔ پودا کتنے انچ لمبا ہے؟" }, answer: 7, answerUnit: { en: "inches", es: "pulgadas", ur: "انچ" } },
        { id: "wp-2.9A-2", emoji: "♻️🧱", scene: "Recycling center measuring a sorting bin's width with centimeter cubes", prompt: { en: "A recycling bin's width is covered by 15 centimeter cubes laid end-to-end. How many centimeters wide is the bin?", es: "El ancho de un contenedor de reciclaje está cubierto por 15 cubos de un centímetro de extremo a extremo. ¿Cuántos centímetros de ancho tiene?", ur: "ری سائیکلنگ ڈبے کی چوڑائی 15 سینٹی میٹر کیوبز سے ڈھکی ہوئی ہے۔ ڈبہ کتنے سینٹی میٹر چوڑا ہے؟" }, answer: 15, answerUnit: { en: "centimeters", es: "centímetros", ur: "سینٹی میٹر" } },
        { id: "wp-2.9A-3", emoji: "🌊🐚", scene: "Beach cleanup team measuring a large shell found on the shore", prompt: { en: "A shell found during a beach cleanup is measured with inch tiles. 4 tiles cover half the shell. If the other half is the same length, how many inches long is the whole shell?", es: "Una concha encontrada durante una limpieza de playa se mide con fichas de una pulgada. 4 fichas cubren la mitad de la concha. Si la otra mitad mide lo mismo, ¿cuántas pulgadas mide la concha completa?", ur: "ساحل کی صفائی کے دوران ملنے والی سیپی کو انچ ٹائلوں سے ناپا جاتا ہے۔ 4 ٹائلیں آدھی سیپی کو ڈھانپتی ہیں۔ اگر دوسرا آدھا حصہ اتنا ہی لمبا ہے تو پوری سیپی کتنی لمبی ہے؟" }, answer: 8, answerUnit: { en: "inches", es: "pulgadas", ur: "انچ" } },
        { id: "wp-2.9A-4", emoji: "🌳🪵", scene: "Nature club measuring a fallen branch with centimeter cubes for a compost log", prompt: { en: "A fallen branch is measured with centimeter cubes end-to-end. 10 cubes cover one section and 6 more cubes cover the rest. How many centimeters long is the whole branch?", es: "Una rama caída se mide con cubos de un centímetro de extremo a extremo. 10 cubos cubren una sección y 6 más cubren el resto. ¿Cuántos centímetros mide la rama completa?", ur: "ایک گری ہوئی شاخ کو سینٹی میٹر کیوبز سے ناپا جاتا ہے۔ 10 کیوبز ایک حصے کو اور مزید 6 کیوبز باقی حصے کو ڈھانپتے ہیں۔ پوری شاخ کتنی سینٹی میٹر لمبی ہے؟" }, answer: 16, answerUnit: { en: "centimeters", es: "centímetros", ur: "سینٹی میٹر" } },
        { id: "wp-2.9A-5", emoji: "🐝🌻", scene: "Pollinator garden club measuring the distance between two flower pots with inch tiles", prompt: { en: "Two flower pots are measured apart using inch tiles laid end-to-end with no gaps. It takes 20 tiles to span the distance between them. How many inches apart are the pots?", es: "Dos macetas de flores se miden usando fichas de una pulgada de extremo a extremo, sin espacios. Se necesitan 20 fichas para cubrir la distancia entre ellas. ¿Cuántas pulgadas de distancia hay entre las macetas?", ur: "دو گملوں کے درمیان فاصلہ انچ ٹائلوں سے بغیر خلا کے ناپا جاتا ہے۔ ان کے درمیان فاصلہ ڈھانپنے کے لیے 20 ٹائلیں لگتی ہیں۔ گملے ایک دوسرے سے کتنے انچ دور ہیں؟" }, answer: 20, answerUnit: { en: "inches", es: "pulgadas", ur: "انچ" } },
      ],
